def lua(value, indent=""):
    """Lua literal in the layout WoW writes to SavedVariables (tabs, ["key"] = value, -- [n] on array items)."""
    if isinstance(value, str):
        return '"' + (value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\\n").replace("\r", "\\r")
                      .replace("\0", "\\000")) + '"'
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "nil"
    if isinstance(value, (int, float)):
        return repr(value)
    inner = indent + "\t"
    lines = ["{"]
    if isinstance(value, list):
        lines += [f"{inner}{lua(v, inner)}, -- [{i}]" for i, v in enumerate(value, 1)]
    else:
        for key in sorted(value, key=str):
            shown = lua(key) if isinstance(key, str) else str(key)
            lines.append(f"{inner}[{shown}] = {lua(value[key], inner)},")
    lines.append(indent + "}")
    return "\n".join(lines)


