def series_of(market, observer=None):
    """{item id: series} of one observer (None: the self observer) of an uploaded market."""
    for entry in market["observers"]:
        if (observer is None and entry["self"]) or (observer is not None and entry["obs"] == observer and not entry["self"]):
            return {s["id"]: s for s in entry["items"]}
    return None


def saved_variables(hist=None, db=True, chardb=False):
    parts = []
    if db:
        parts.append("OroHermandadDB = " + lua(guild_db()))
    if hist is not None:
        parts.append("OroHermandadHist = " + lua(hist))
    if chardb:
        parts.append("OroHermandadCharDB = " + lua(char_db()))
    return "\n".join(parts) + "\n"


def write(path, text, age=60):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    os.utime(path, (NOW - age, NOW - age))


def encoded(upload):
    return json.dumps(upload, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")


class Quiet(unittest.TestCase):
    def setUp(self):
        self.output = io.StringIO()
        redirect = contextlib.redirect_stdout(self.output)
        redirect.__enter__()
        self.addCleanup(redirect.__exit__, None, None, None)
        folder = tempfile.TemporaryDirectory()
        self.addCleanup(folder.cleanup)
        self.tmp = Path(folder.name)


