class ReaderTests(Quiet):
    def test_reads_the_wow_layout_with_comments_escapes_and_numbers(self):
        text = ("\ufeff-- cabecera\nOroHermandadHist = {\n\t[\"a\"] = \"x\\\"y\\\\z\\\nw\\r\\000\\65\\t\", -- comentario\n"
                "\t[\"b\"] = { 1, -- [1]\n\t\t-2.5, -- [2]\n\t\t0x1F, 1e3, .5, }, --[==[ largo\n]] ]==]\n"
                "\tc = true; d = false, [\"e\"] = nil, [3] = 'simple', [4.0] = [[\nlargo]],\n}\n")
        hist = h.extract_hist(text)
        self.assertEqual(hist, {"a": 'x"y\\z\nw\r\x00A\t', "b": {1: 1, 2: -2.5, 3: 31, 4: 1000, 5: 0.5},
                                "c": True, "d": False, "e": None, 3: "simple", 4: "largo"})
        self.assertIs(type(hist["b"][4]), int)

    def test_other_globals_are_walked_but_never_built(self):
        text = saved_variables(sample_hist(), db=True, chardb=True)
        found = h.read_globals(text, {"OroHermandadHist"})
        self.assertEqual(list(found), ["OroHermandadHist"])
        self.assertEqual(found["OroHermandadHist"], h.read_globals(text, {"OroHermandadDB", "OroHermandadHist"})["OroHermandadHist"])
        self.assertNotIn("Zaraguinda", repr(found))
        self.assertIsNone(h.extract_hist(saved_variables(None, chardb=True)))

    def test_non_finite_numbers_in_other_data_do_not_block_the_upload(self):
        text = "OroHermandadDB = { x = 1.#INF, y = -1.#IND, z = nan, w = -inf, v = -nan(ind) }\n" + \
               "OroHermandadHist = " + lua(sample_hist()) + "\n"
        self.assertEqual(h.extract_hist(text), h.extract_hist(saved_variables(sample_hist(), db=False)))
        values = h.read_globals(text, {"OroHermandadDB"})["OroHermandadDB"]
        self.assertEqual(values["x"], float("inf"))
        self.assertEqual(values["w"], float("-inf"))
        self.assertTrue(all(v != v for v in (values["y"], values["z"], values["v"])))

    def test_never_runs_or_accepts_code(self):
        for text in ("x = function() end", "x = os.execute('rm -rf /')", "local x = 1", "x = {f()}", "x = 1 + 2",
                     "x = 'a' .. 'b'", "x = y", "x = {[f()] = 1}", "return {}", "x = {end = 1}", "x = {[true] = 1}",
                     "x = {[{}] = 1}", "x = {[0/0] = 1}", "x = {1 2}", "x = {", "x = \"abierto", "x = 'a\nb'",
                     "x = '\\q'", "x = '\\256'", "x = --[[ sin cerrar", "x = [[ sin cerrar", "x = 12abc", "x = 1.2.3",
                     "x = {a = 1, a = 2}", "x = {[1] = 'a', 'b'}", "x = 1\nx = 2", "x", "x = ", "1 = 2", "x = {[\"a\"] 1}",
                     "x = 0x", "x = " + "9" * 65, "x = {} y = {} z = {} if", "x = 5y = 6", "x = {1e}"):
            with self.subTest(text=text), self.assertRaises(h.LuaFormatError) as raised:
                h.read_globals(text, {"x"})
            self.assertIn("(línea", str(raised.exception))
        # The same checks apply to a global that is only skipped.
        with self.assertRaises(h.LuaFormatError):
            h.read_globals("OroHermandadDB = { a = f() }\nOroHermandadHist = {}", {"OroHermandadHist"})

    def test_errors_never_quote_the_file(self):
        with self.assertRaises(h.LuaFormatError) as raised:
            h.extract_hist(saved_variables(None) + "OroHermandadHist = { Zaraguinda }")
        self.assertNotIn("Zaraguinda", str(raised.exception))

    def test_limits_depth_nodes_strings_and_size(self):
        deep = "x = " + "{" * 32 + "}" * 32                     # same depth rule as src/auctioneer.mjs (30)
        with self.assertRaises(h.LuaFormatError):
            h.read_globals(deep, {"x"})
        with self.assertRaises(h.LuaFormatError):
            h.read_globals(deep + "\ny = 1", {"y"})
        self.assertEqual(h.read_globals("x = " + "{" * 31 + "}" * 31, {"x"})["x"].__class__, dict)
        many = "x = {" + "1," * 1000 + "}"
        with self.assertRaises(h.LuaFormatError):
            h.read_globals(many, {"x"}, {"nodes": 500})
        with self.assertRaises(h.LuaFormatError):   # skipped globals count too
            h.read_globals(many + "\ny = 1", {"y"}, {"nodes": 500})
        with self.assertRaises(h.LuaFormatError):
            h.read_globals("x = '" + "a" * 2000 + "'", {"x"}, {"string_bytes": 1000})
        with self.assertRaises(h.LuaFormatError):
            h.read_globals("y = '" + "a" * 2000 + "'", {"x"}, {"string_bytes": 1000})
        with self.assertRaises(h.LuaFormatError):
            h.read_globals("x = '" + "ñ" * 600 + "'", {"x"}, {"string_bytes": 1000})
        with self.assertRaises(h.LuaFormatError):
            h.read_globals("x = 1", {"x"}, {"chars": 3})
        self.assertEqual(h.read_globals("x = '" + "a" * 1000 + "'", {"x"}, {"string_bytes": 1000})["x"], "a" * 1000)


