class SourceTests(Quiet):
    def make_install(self):
        root = self.tmp / "World of Warcraft"
        accounts = root / "_forever_" / "WTF" / "Account"
        write(accounts / "CUENTA1" / "SavedVariables" / "OroHermandad.lua", saved_variables(sample_hist()))
