    def test_finds_every_account_from_any_folder_the_player_picks(self):
        root, accounts = self.make_install()
        expected = [("123456#2", accounts / "123456#2" / "SavedVariables" / "OroHermandad.lua"),
                    ("CUENTA1", accounts / "CUENTA1" / "SavedVariables" / "OroHermandad.lua"),
                    ("SINADDON", accounts / "SINADDON" / "SavedVariables" / "OroHermandad.lua")]
        for folder in (root, root / "_forever_", root / "_forever_" / "WTF", accounts):
            with self.subTest(folder=folder):
                self.assertEqual([(s.account, s.path) for s in h.find_sources(folder)], expected)
                self.assertEqual(h.validate_wow_folder(str(folder)), folder.resolve())
        one = accounts / "CUENTA1" / "SavedVariables"
        self.assertEqual([(s.account, s.path) for s in h.find_sources(one)], [("CUENTA1", one / "OroHermandad.lua")])
        empty = accounts / "SINADDON" / "SavedVariables"
        self.assertEqual([(s.account, s.path) for s in h.find_sources(empty)], [("SINADDON", empty / "OroHermandad.lua")])
        self.assertEqual(h.validate_wow_folder(empty), empty.resolve())
        self.assertEqual(h.find_sources(self.tmp / "nada"), [])
        for bad in ("", "\\\\servidor\\wow", "//servidor/wow", str(self.tmp / "nada"), str(self.tmp), None):
            with self.subTest(bad=bad), self.assertRaises(h.SyncError):
                h.validate_wow_folder(bad)
        fresh = self.tmp / "Nuevo"
        (fresh / "_forever_").mkdir(parents=True)
        self.assertEqual(h.validate_wow_folder(f'"{fresh}"'), fresh.resolve())
        self.assertEqual(h.find_sources(fresh), [])

    def test_detects_common_install_folders(self):
        root, _ = self.make_install()
        program_files = self.tmp / "Program Files (x86)"
        (program_files / "World of Warcraft" / "_forever_").mkdir(parents=True)
        env = {"ProgramFiles(x86)": str(program_files), "ProgramFiles": str(self.tmp / "nada"),
               "PUBLIC": str(self.tmp / "Public")}
        with patch.object(h, "_windows", return_value=True), patch.object(h, "_fixed_drives", return_value=[]):
            self.assertEqual(h.detect_wow_folders(env), [(program_files / "World of Warcraft").resolve()])
        with patch.object(h, "_windows", return_value=False), patch.object(Path, "home", return_value=self.tmp):
            (self.tmp / "Games").mkdir()
            os.symlink(root, self.tmp / "Games" / "World of Warcraft")
            self.assertEqual(h.detect_wow_folders({}), [root.resolve()])


