class Response:
    def __init__(self, body):
        self.body = body

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False

    def read(self, limit):
        return self.body[:limit]


class HttpTests(unittest.TestCase):
    def test_https_only(self):
        self.assertEqual(h.validate_panel_url("https://ESPECULADOR.example.com/"), URL)
        self.assertEqual(h.validate_panel_url(URL + "/hermandad"), URL)
        self.assertEqual(h.validate_panel_url(URL + "/hermandad.html"), URL)
        for value in ("http://especulador.example.com", "http://especulador.example.com/hermandad", URL + "/api/guild/sync",
                      "https://user:pass@especulador.example.com", URL + "?k=" + KEY, URL + "#x", "https://localhost",
                      "http://127.0.0.1:8787", "ftp://especulador.example.com", "", None, "https://bad host.example"):
            with self.subTest(value=value), self.assertRaises(h.SyncError) as raised:
                h.validate_panel_url(value, env={})
            self.assertNotIn("aplicación", str(raised.exception))

