class FakeDpapi:
    """CryptProtectData / CryptUnprotectData / LocalFree stand-ins that really read and write DATA_BLOB memory."""
    MARK = b"FAKE-DPAPI:"

    def __init__(self):
        self.calls, self.buffers, self.freed, self.fail = [], [], [], False
        self.api = h._DpapiApi(protect=lambda *a: self.run("protect", *a), unprotect=lambda *a: self.run("unprotect", *a),
                               local_free=lambda pointer: self.freed.append(pointer.value))

    def run(self, kind, data_in, description, entropy, reserved, prompt, flags, data_out):
        raw = ctypes.string_at(data_in.contents.pbData, data_in.contents.cbData)
        salt = ctypes.string_at(entropy.contents.pbData, entropy.contents.cbData)
        self.calls.append((kind, description, salt, reserved, prompt, flags))
        if self.fail or (kind == "unprotect" and not raw.startswith(self.MARK)):
            return 0
        out = self.MARK + bytes(b ^ 0x5A for b in raw) if kind == "protect" else bytes(b ^ 0x5A for b in raw[len(self.MARK):])
        buffer = ctypes.create_string_buffer(out, len(out))
        self.buffers.append(buffer)
        data_out.contents.cbData = len(out)
        data_out.contents.pbData = ctypes.cast(buffer, ctypes.POINTER(ctypes.c_char))
        return 1


class KeyTests(Quiet):
    def test_dpapi_round_trip_through_real_ctypes_blobs(self):
        fake = FakeDpapi()
        protector = h.DpapiProtector(fake.api)
        sealed = h.seal_key(KEY, protector)
        self.assertEqual(sealed["protection"], "dpapi")
        self.assertEqual(h.open_key(sealed, protector), KEY)
        self.assertEqual([c[0] for c in fake.calls], ["protect", "unprotect", "unprotect"])
        self.assertEqual(fake.calls[0][1:], ("Oro de Hermandad", h.DpapiProtector.ENTROPY, None, None, 1))
        self.assertIsNone(fake.calls[1][1])
        self.assertEqual(len(fake.freed), 3)
        self.assertTrue(all(buffer.raw == b"\0" * len(buffer.raw) for buffer in fake.buffers))  # outputs wiped
        fake.fail = True
        with self.assertRaises(h.KeyStoreError):
            protector.protect(b"x")
        self.assertIsNone(h.open_key(sealed, protector))
        fake.fail = False
        for broken in ({"protection": "dpapi", "data": "!!"}, {"protection": "dpapi", "data": "QUJD"}, {"protection": "otra"},
                       None, "texto"):
            self.assertIsNone(h.open_key(broken, protector))

