    def runner(self, code=0):
        def run(args, **kwargs):
            self.calls.append((args, kwargs))
            if "/XML" in args:                      # the definition only exists while schtasks reads it
                self.task_file = Path(args[args.index("/XML") + 1])
                self.task_xml = self.task_file.read_bytes()
            return SimpleNamespace(returncode=code, stdout="", stderr="")
        return run

    @staticmethod
    def parse_task(raw):
        """{"Settings/StopIfGoingOnBatteries": "false", ...} of a task definition written by install_startup."""
        import xml.etree.ElementTree as ElementTree
        assert raw.startswith(b"\xff\xfe"), "UTF-16 with a byte order mark, as schtasks expects"
        assert raw.decode("utf-16").startswith('<?xml version="1.0" encoding="UTF-16"?>')
        root = ElementTree.fromstring(raw)
        space = "{http://schemas.microsoft.com/windows/2004/02/mit/task}"
        assert root.tag == space + "Task" and root.get("version") == "1.2"
        out = {}
        def walk(node, prefix):
            for child in node:
                name = prefix + child.tag.replace(space, "")
                if len(child):
                    walk(child, name + "/")
                else:
                    assert name not in out, f"{name} repetido"
                    out[name] = child.text
        walk(root, "")
        return out

    def test_startup_task_install_and_removal(self):
        exe = self.tmp / "Python312" / "python.exe"
        exe.parent.mkdir()
        exe.write_text("")
        (exe.parent / "pythonw.exe").write_text("")
        env = {"USERNAME": "Jugador", "USERDOMAIN": "PC-CASA"}
        with patch.object(h, "_windows", return_value=True):
            h.install_startup(self.runner(), env=env, executable=exe, script=HERE / "hermandad.py", home=self.home)
            args, kwargs = self.calls[-1]
            self.assertEqual(args, ["schtasks", "/Create", "/TN", h.TASK_NAME, "/XML", str(self.task_file), "/F"])
            self.assertIs(kwargs["stdin"], h.subprocess.DEVNULL)
            self.assertFalse(self.task_file.exists(), "the task definition is deleted after schtasks reads it")
            self.assertNotIn(KEY, " ".join(args))
            self.assertNotIn(KEY.encode("utf-16-le"), self.task_xml)
            self.assertIn("Listo: el subidor arrancará", self.output.getvalue())
            task = self.parse_task(self.task_xml)
            self.assertEqual(task["Triggers/LogonTrigger/UserId"], "PC-CASA\\Jugador")
            self.assertEqual(task["Triggers/LogonTrigger/Delay"], "PT1M")
            self.assertEqual(task["Principals/Principal/UserId"], "PC-CASA\\Jugador")
            self.assertEqual(task["Principals/Principal/LogonType"], "InteractiveToken", "only while the user is logged on")
            self.assertEqual(task["Principals/Principal/RunLevel"], "LeastPrivilege")
            for setting, value in (("DisallowStartIfOnBatteries", "false"), ("StopIfGoingOnBatteries", "false"),
                                   ("ExecutionTimeLimit", "PT0S"), ("MultipleInstancesPolicy", "IgnoreNew"),
                                   ("Enabled", "true"), ("RunOnlyIfIdle", "false")):
                self.assertEqual(task["Settings/" + setting], value, setting)
            self.assertEqual(task["Actions/Exec/Command"], f'"{exe.parent / "pythonw.exe"}"')
            self.assertEqual(task["Actions/Exec/Arguments"], f'"{HERE / "hermandad.py"}" --segundo-plano')
            self.assertEqual(task["Actions/Exec/WorkingDirectory"], str(HERE))
            # Paths with XML characters stay intact, and without USERNAME the task has no fixed user.
            odd = self.tmp / "Tom & Jerry <1>"
            odd.mkdir()
            (odd / "hermandad.py").write_text("")
            with patch.object(h, "TASK_COMMAND_MAX", 10_000):          # whatever the length of the temporary folder
                h.install_startup(self.runner(), env={}, executable=exe, script=odd / "hermandad.py", home=self.home)
            task = self.parse_task(self.task_xml)
            self.assertEqual(task["Actions/Exec/Arguments"], f'"{odd / "hermandad.py"}" --segundo-plano')
            self.assertNotIn("Triggers/LogonTrigger/UserId", task)
            self.assertNotIn("Principals/Principal/UserId", task)
            with self.assertRaises(h.SyncError) as raised:
                h.install_startup(self.runner(1), env=env, executable=exe, script=HERE / "hermandad.py")
            self.assertIn("administrador", str(raised.exception))
            with self.assertRaises(h.SyncError):
                h.install_startup(self.runner(), env=env, executable=exe, script=self.tmp / ("x" * 250) / "hermandad.py")
            h.uninstall_startup(self.runner())
            self.assertEqual(self.calls[-1][0], ["schtasks", "/Delete", "/TN", h.TASK_NAME, "/F"])
            h.uninstall_startup(self.runner(1))
            self.assertIn("No había ninguna tarea de inicio", self.output.getvalue())
            self.assertEqual(self.main(["--instalar-inicio"], answers=[URL, ""], runner=self.runner()), 0)
            self.assertEqual(self.calls[-1][0][:5], ["schtasks", "/Create", "/TN", h.TASK_NAME, "/XML"])
            self.assertIn("--segundo-plano", self.parse_task(self.task_xml)["Actions/Exec/Arguments"])
            self.assertEqual(self.main(["--quitar-inicio"], runner=self.runner()), 0)
        with patch.object(h, "_windows", return_value=False):
            self.assertEqual(self.main(["--instalar-inicio"], runner=self.runner()), 1)
            self.assertEqual(self.main(["--quitar-inicio"], runner=self.runner()), 1)
        self.assertIn("solo existe en Windows", self.output.getvalue())

