        with patch.object(h, "MAX_OBS_PROGRESS", 1):
            self.assertEqual(list(h.accepted_progress(None, posted, {})["A-Alliance"]["obs"]), ["bbbb0002"])
        self.assertIsNone(h._progress(fresh, "A-Alliance", "bbbb0009"))
